<section aria-labelledby="purchase-title"><div class="contact-toolbar"><div><p class="eyebrow">COMPRAS · ÓRDENES</p><h1 id="purchase-title">Solicitudes de cotización</h1><p class="section-subtitle"><?= $page['total'] ?> registros</p></div><a class="contact-button contact-button-primary" href="index.php?new=1">+ Nueva solicitud</a></div>
    <form class="contact-filters" method="get" action="index.php"><?php foreach(['pending','unpaid','overdue'] as $summaryFilter): ?><?php if(($_GET[$summaryFilter]??'')==='1'): ?><input type="hidden" name="<?= $summaryFilter ?>" value="1"><?php endif; ?><?php endforeach; ?><label>Buscar<input name="q" type="search" maxlength="160" value="<?= salesEscape($page['search']) ?>" placeholder="Referencia o proveedor"></label><label>Estado<select name="status" data-auto-submit><option value="all">Todos</option><?php foreach (purchaseStatuses() as $value => $label): ?><option value="<?= $value ?>" <?= $page['statusFilter'] === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></label><button class="contact-button" type="submit">Buscar</button></form>
    <div class="contact-table-wrap"><table class="contact-table"><thead><tr><th scope="col">Referencia</th><th scope="col">Proveedor</th><th scope="col">Fecha</th><th scope="col">Estado</th><th scope="col">Total</th></tr></thead><tbody><?php foreach ($page['rows'] as $row): ?><tr><td><a class="contact-name" href="index.php?id=<?= (int) $row['id'] ?>"><?= salesEscape($row['name']) ?></a></td><td><?= salesEscape($row['supplier_name']) ?></td><td><?= salesEscape($row['order_date']) ?></td><td><?= purchaseStatuses()[$row['status']] ?></td><td><?= salesEscape($row['total_amount'].' '.$row['currency_code']) ?></td></tr><?php endforeach; ?><?php if (! $page['rows']): ?><tr><td colspan="5" class="contact-empty">No hay solicitudes que coincidan con los filtros.</td></tr><?php endif; ?></tbody></table></div>
    <nav class="contact-pagination"><span>Página <?= $page['currentPage'] ?> de <?= $page['pages'] ?></span><?php foreach (['Anterior' => $page['currentPage'] - 1, 'Siguiente' => $page['currentPage'] + 1] as $label => $number): ?><?php if ($number >= 1 && $number <= $page['pages']): ?><a class="contact-button" href="index.php?<?= salesEscape(http_build_query(['q' => $page['search'], 'status' => $page['statusFilter'], 'page' => $number,'pending'=>(($_GET['pending']??'')==='1'?'1':null),'unpaid'=>(($_GET['unpaid']??'')==='1'?'1':null),'overdue'=>(($_GET['overdue']??'')==='1'?'1':null)])) ?>"><?= $label ?></a><?php endif; ?><?php endforeach; ?></nav>
</section>
